module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic s,
    input  logic w,
    output logic z
);

    typedef enum logic [1:0] {
        A   = 2'b00,
        S0  = 2'b01,
        S1  = 2'b10,
        S2  = 2'b11
    } state_t;

    state_t state, next_state;
    logic w_a, w_b, w_c;

    // State transition logic
    always_comb begin
        next_state = state;
        case (state)
            A: begin
                if (s) next_state = S0;
                else   next_state = A;
            end
            S0: next_state = S1;
            S1: next_state = S2;
            S2: next_state = S0;
            default: next_state = A;
        endcase
    end

    // Sequential logic (state, outputs, and sample storage)
    always_ff @(posedge clk) begin
        if (reset) begin
            state <= A;
            z     <= 1'b0;
            w_a   <= 1'b0;
            w_b   <= 1'b0;
            w_c   <= 1'b0;
        end else begin
            state <= next_state;
            case (next_state)
                A: begin
                    z   <= 1'b0;
                end
                S0: begin
                    if (state == S2) begin
                        z <= ((w_a + w_b + w_c) == 2);
                    end else begin
                        z <= 1'b0;
                    end
                    w_a <= w;
                end
                S1: begin
                    z   <= 1'b0;
                    w_b <= w;
                end
                S2: begin
                    z   <= 1'b0;
                    w_c <= w;
                end
                default: begin
                    z <= 1'b0;
                end
            endcase
        end
    end

endmodule

