module tb_TopModule;
    logic clk;
    logic reset;
    logic s;
    logic w;
    logic z;

    // Instantiate TopModule
    TopModule uut (
        .clk(clk),
        .reset(reset),
        .s(s),
        .w(w),
        .z(z)
    );

    // Clock generator
    initial clk = 0;
    always #5 clk = ~clk;

    // Task to apply inputs and check expected z
    // We run test vectors synchronously
    initial begin
        reset = 1;
        s = 0;
        w = 0;
        #12;
        reset = 0;

        // While s=0, z should be 0
        @(posedge clk);
        #1;
        assert(z == 0) else $error("Failed at reset/idle s=0");

        @(posedge clk);
        #1;
        assert(z == 0) else $error("Failed at reset/idle s=0");

        // Now assert s=1 and feed w sequence: 1, 1, 0 (Window 1) -> expect z=1 on cycle 4
        s = 1;
        w = 1; // cycle 1 of window 1
        @(posedge clk); #1; // enters S0, sampled w=1
        assert(z == 0) else $error("z should be 0 at cycle 1");

        w = 1; // cycle 2 of window 1
        @(posedge clk); #1; // enters S1, sampled w=1
        assert(z == 0) else $error("z should be 0 at cycle 2");

        w = 0; // cycle 3 of window 1
        @(posedge clk); #1; // enters S2, sampled w=0
        assert(z == 0) else $error("z should be 0 at cycle 3");

        // Now entering cycle 4 (start of window 2), sum should be 2, so z should be 1
        w = 1; // cycle 1 of window 2
        @(posedge clk); #1; // enters S0
        assert(z == 1) else $error("z should be 1 after window 1 (sum=2)");

        // Window 2: w = 1, 0, 0 -> sum = 1 -> expect z=0 at start of window 3
        w = 0; // cycle 2 of window 2
        @(posedge clk); #1; // enters S1
        assert(z == 0) else $error("z should be 0 at cycle 2 of window 2");

        w = 0; // cycle 3 of window 2
        @(posedge clk); #1; // enters S2
        assert(z == 0) else $error("z should be 0 at cycle 3 of window 2");

        // Start of window 3: sum=1, expect z=0
        w = 1; // cycle 1 of window 3
        @(posedge clk); #1; // enters S0
        assert(z == 0) else $error("z should be 0 after window 2 (sum=1)");

        w = 1; // cycle 2 of window 3
        @(posedge clk); #1; // enters S1
        assert(z == 0) else $error("z should be 0 at cycle 2 of window 3");

        w = 1; // cycle 3 of window 3 (sum = 3)
        @(posedge clk); #1; // enters S2
        assert(z == 0) else $error("z should be 0 at cycle 3 of window 3");

        // Start of window 4: sum=3, expect z=0
        w = 0; // cycle 1 of window 4
        @(posedge clk); #1; // enters S0
        assert(z == 0) else $error("z should be 0 after window 3 (sum=3)");

        w = 1; // cycle 2 of window 4
        @(posedge clk); #1; // enters S1
        assert(z == 0) else $error("z should be 0 at cycle 2 of window 4");

        w = 1; // cycle 3 of window 4 (sum = 2)
        @(posedge clk); #1; // enters S2
        assert(z == 0) else $error("z should be 0 at cycle 3 of window 4");

        // Start of window 5: sum=2, expect z=1
        w = 0;
        @(posedge clk); #1; // enters S0
        assert(z == 1) else $error("z should be 1 after window 4 (sum=2)");

        // Test reset during operation
        reset = 1;
        @(posedge clk); #1;
        assert(z == 0) else $error("z should be 0 after reset");
        reset = 0;

        // After reset, s=0, should stay in A
        s = 0;
        @(posedge clk); #1;
        assert(z == 0) else $error("z should be 0 in state A after reset");

        $display("SELFTEST PASS");
        $finish;
    end

endmodule
